INSERT INTO landing_pages (slug, label, is_published, cta_region_slug, image_url, image_alt, sort_order, h1_en, intro_en, content_en, meta_title_en, meta_description_en, h1_de, intro_de, content_de, meta_title_de, meta_description_de, h1_pl, intro_pl, content_pl, meta_title_pl, meta_description_pl, h1_ru, intro_ru, content_ru, meta_title_ru, meta_description_ru, h1_tr, intro_tr, content_tr, meta_title_tr, meta_description_tr, h1_nl, intro_nl, content_nl, meta_title_nl, meta_description_nl, h1_ro, intro_ro, content_ro, meta_title_ro, meta_description_ro)
SELECT 'lara-beach-transfer', 'Lara Beach Transfer', true, 'kundu-lara', 'C:/Program Files/Git/images/regions/kundu-lara.jpg', 'Lara Beach Kundu hotels transfer from Antalya Airport', 101, 'Antalya Airport → Lara Beach Transfer', 'Private VIP transfer to Lara Beach hotels — Aska Lara, Titanic Lara, Royal Seginus. Fixed price, no taxis, no waiting.', '<p>Lara Beach (Kundu) is one of Antalya''s most popular resort areas, home to some of Turkey''s finest 5-star hotels. Located just 15 km east of Antalya Airport (AYT), it''s the closest major resort destination — only ~20 minutes by private transfer. Skip the taxi queue and arrive in comfort.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>Why choose a private transfer over a taxi? Fixed price agreed upfront, professional driver with name sign, free flight delay waiting — no surprises.</p><h2>Why Choose TORVIAN for Lara Beach?</h2><ul><li>Direct door-to-door from Antalya Airport (AYT) to Lara Beach</li><li>Fixed price — no meter, no surge, no haggling</li><li>Meet &amp; greet: driver with name sign at arrivals hall</li><li>Free flight tracking — we wait if your flight is delayed</li><li>Mercedes Vito VIP with A/C, Wi-Fi &amp; child seats available</li><li>Free cancellation up to 24 hours before departure</li><li>24/7 WhatsApp support in English</li><li>Covers all Lara Beach hotels: Aska Lara, Titanic, Royal Seginus &amp; more</li></ul><h2>Frequently Asked Questions</h2><h3>How far is Lara Beach from Antalya Airport?</h3><p>Lara Beach (Kundu area) is approximately 15 km from Antalya Airport (AYT). A private transfer takes around 20 minutes — making it the closest major resort area to the airport.</p><h3>Is a private transfer cheaper than a taxi from Antalya Airport to Lara Beach?</h3><p>TORVIAN private transfers offer a fixed price agreed before your journey — unlike taxis where the meter runs. There are no hidden fees, no surge pricing, and your driver waits free of charge if your flight is delayed.</p><h3>Which hotels in Lara Beach do you serve?</h3><p>We serve all hotels in the Lara Beach and Kundu area, including Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace, and all others. Just enter your hotel name during booking.</p><h3>Can I book a return transfer from Lara Beach to Antalya Airport?</h3><p>Yes. We offer both one-way and round-trip transfers. Book your return transfer from Lara Beach to Antalya Airport during the same booking and receive a discounted combined price.</p><h3>How do I find my driver at Antalya Airport?</h3><p>Your driver will be waiting at the arrivals hall with a name sign showing your name. We track your flight in real time — if your flight is delayed, your driver will still be there at no extra charge.</p>', 'Antalya Airport to Lara Beach Transfer | Private VIP | ~20 min', 'Private VIP transfer from Antalya Airport to Lara Beach (Kundu). ~20 min, 15 km. Fixed price, meet & greet, free flight tracking. Better than taxi — book online in 2 minutes.', 'Flughafen Antalya → Lara Beach Transfer', 'Privater VIP-Transfer zu Lara Beach Hotels — Aska Lara, Titanic Lara, Royal Seginus. Festpreis, kein Taxi, kein Warten.', '<p>Lara Beach (Kundu) ist eines der beliebtesten Resortgebiete Antalyas und beherbergt einige der besten 5-Sterne-Hotels der Türkei. Nur 15 km östlich vom Flughafen Antalya (AYT) gelegen, ist es das nächste große Resort — nur ~20 Minuten mit dem Privattransfer.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>Warum Privattransfer statt Taxi? Fester Preis im Voraus, professioneller Fahrer mit Namensschild, kostenlose Wartezeit bei Flugverspätung — keine Überraschungen.</p><h2>Warum TORVIAN für Lara Beach?</h2><ul><li>Direkttransfer vom Flughafen Antalya (AYT) nach Lara Beach</li><li>Festpreis — kein Taxameter, keine Preisschwankungen</li><li>Meet &amp; Greet mit Namensschild in der Ankunftshalle</li><li>Kostenlose Flugverfolgung — wir warten bei Verspätung</li><li>Mercedes Vito VIP mit Klimaanlage, WLAN &amp; Kindersitzen</li><li>Kostenlose Stornierung bis 24 Stunden vorher</li><li>24/7 WhatsApp-Support auf Deutsch</li><li>Alle Lara Beach Hotels: Aska Lara, Titanic, Royal Seginus &amp; mehr</li></ul><h2>Häufig gestellte Fragen</h2><h3>Wie weit ist Lara Beach vom Flughafen Antalya entfernt?</h3><p>Lara Beach (Kundu-Gebiet) liegt etwa 15 km vom Flughafen Antalya (AYT) entfernt. Ein Privattransfer dauert etwa 20 Minuten — damit ist es das nächste große Resortgebiet vom Flughafen.</p><h3>Ist ein Privattransfer günstiger als ein Taxi vom Flughafen Antalya nach Lara Beach?</h3><p>TORVIAN Privattransfers bieten einen vorab vereinbarten Festpreis — kein laufendes Taxameter. Keine versteckten Gebühren, keine Preisschwankungen, und Ihr Fahrer wartet kostenlos bei Flugverspätung.</p><h3>Welche Hotels in Lara Beach bedienen Sie?</h3><p>Wir bedienen alle Hotels in Lara Beach und Kundu, darunter Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace und alle anderen. Geben Sie einfach Ihren Hotelnamen bei der Buchung ein.</p><h3>Kann ich einen Rücktransfer von Lara Beach zum Flughafen buchen?</h3><p>Ja. Wir bieten sowohl einfache als auch Hin- und Rückfahrten an. Buchen Sie den Rücktransfer von Lara Beach zum Flughafen Antalya bei derselben Buchung und erhalten Sie einen vergünstigten Kombinationspreis.</p><h3>Wie finde ich meinen Fahrer am Flughafen Antalya?</h3><p>Ihr Fahrer wartet in der Ankunftshalle mit einem Schild mit Ihrem Namen. Wir verfolgen Ihren Flug in Echtzeit — bei Verspätung ist Ihr Fahrer trotzdem da, ohne Aufpreis.</p>', 'Flughafen Antalya nach Lara Beach Transfer | Privat VIP | ~20 Min', 'Privater VIP-Transfer vom Flughafen Antalya nach Lara Beach (Kundu). ~20 Min, 15 km. Festpreis, Meet & Greet, kostenlose Flugverfolgung. Besser als Taxi — in 2 Min. buchen.', 'Lotnisko Antalya → Transfer Lara Beach', 'Prywatny transfer VIP do hoteli Lara Beach — Aska Lara, Titanic Lara, Royal Seginus. Stała cena, bez taksówek, bez czekania.', '<p>Lara Beach (Kundu) to jeden z najpopularniejszych kurortów w Antalyi, mieszczący najlepsze 5-gwiazdkowe hotele w Turcji. Zaledwie 15 km na wschód od lotniska Antalya (AYT) — to najbliższy duży kurort, tylko ~20 minut prywatnym transferem.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>Dlaczego prywatny transfer zamiast taksówki? Stała cena ustalona z góry, profesjonalny kierowca z tabliczką, bezpłatne czekanie przy opóźnieniu lotu.</p><h2>Dlaczego TORVIAN do Lara Beach?</h2><ul><li>Bezpośredni transfer z lotniska Antalya (AYT) do Lara Beach</li><li>Stała cena — bez licznika, bez zmiennych opłat</li><li>Powitanie z tabliczką z nazwiskiem w hali przylotów</li><li>Bezpłatne śledzenie lotu — czekamy przy opóźnieniu</li><li>Mercedes Vito VIP z klimatyzacją, Wi-Fi i fotelikami</li><li>Bezpłatna anulacja do 24 godzin wcześniej</li><li>Wsparcie WhatsApp 24/7 po polsku</li><li>Wszystkie hotele w Lara Beach: Aska Lara, Titanic, Royal Seginus i inne</li></ul><h2>Najczęściej zadawane pytania</h2><h3>Jak daleko jest Lara Beach od lotniska Antalya?</h3><p>Lara Beach (obszar Kundu) leży około 15 km od lotniska Antalya (AYT). Transfer prywatnym pojazdem trwa około 20 minut — to najbliższy duży kurort od lotniska.</p><h3>Czy prywatny transfer jest tańszy niż taksówka z lotniska Antalya do Lara Beach?</h3><p>Transfery TORVIAN mają stałą cenę ustaloną przed podróżą — w przeciwieństwie do taksówek z licznikiem. Brak ukrytych opłat i bezpłatne czekanie przy opóźnieniu lotu.</p><h3>Jakie hotele w Lara Beach obsługujecie?</h3><p>Obsługujemy wszystkie hotele w Lara Beach i Kundu: Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace i wszystkie inne. Podaj nazwę hotelu podczas rezerwacji.</p><h3>Czy mogę zarezerwować transfer powrotny z Lara Beach na lotnisko?</h3><p>Tak. Oferujemy transfery w jedną stronę i w obie strony. Zarezerwuj transfer powrotny z Lara Beach na lotnisko Antalya w tej samej rezerwacji i otrzymaj zniżkę.</p><h3>Jak znaleźć kierowcę na lotnisku Antalya?</h3><p>Kierowca czeka w hali przylotów z tabliczką z Twoim nazwiskiem. Śledzimy Twój lot na bieżąco — przy opóźnieniu kierowca nadal na Ciebie czeka, bez dodatkowych kosztów.</p>', 'Transfer Lotnisko Antalya — Lara Beach | Prywatny VIP | ~20 min', 'Prywatny transfer VIP z lotniska Antalya do Lara Beach (Kundu). ~20 min, 15 km. Stała cena, powitanie, śledzenie lotu. Lepsza opcja niż taksówka — rezerwacja online 2 min.', 'Аэропорт Анталья → Трансфер Пляж Лара', 'Частный VIP-трансфер в отели Лара — Aska Lara, Titanic Lara, Royal Seginus. Фиксированная цена, без такси, без ожидания.', '<p>Пляж Лара (Кунду) — один из самых популярных курортных районов Антальи, в котором расположены лучшие 5-звёздочные отели Турции. Всего в 15 км к востоку от аэропорта Анталья (AYT) — это ближайший крупный курорт, всего ~20 минут на частном трансфере.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>Почему частный трансфер лучше такси? Фиксированная цена заранее, профессиональный водитель с табличкой, бесплатное ожидание при задержке рейса.</p><h2>Почему TORVIAN для пляжа Лара?</h2><ul><li>Прямой трансфер из аэропорта Анталья (AYT) на пляж Лара</li><li>Фиксированная цена — без счётчика, без скачков цены</li><li>Встреча с табличкой с именем в зале прилёта</li><li>Бесплатное отслеживание рейса — ждём при задержке</li><li>Mercedes Vito VIP с кондиционером, Wi-Fi и детскими креслами</li><li>Бесплатная отмена за 24 часа до поездки</li><li>Поддержка WhatsApp 24/7 на русском языке</li><li>Все отели пляжа Лара: Aska Lara, Titanic, Royal Seginus и другие</li></ul><h2>Часто задаваемые вопросы</h2><h3>Как далеко пляж Лара от аэропорта Анталья?</h3><p>Пляж Лара (район Кунду) находится примерно в 15 км от аэропорта Анталья (AYT). Частный трансфер займёт около 20 минут — это ближайший крупный курорт к аэропорту.</p><h3>Частный трансфер дешевле такси из аэропорта Анталья на пляж Лара?</h3><p>Трансферы TORVIAN имеют фиксированную цену, согласованную до поездки — в отличие от такси со счётчиком. Никаких скрытых платежей и бесплатное ожидание при задержке рейса.</p><h3>В какие отели на пляже Лара вы возите?</h3><p>Мы обслуживаем все отели на пляже Лара и в Кунду: Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace и все остальные. Просто введите название отеля при бронировании.</p><h3>Можно заказать обратный трансфер с пляжа Лара в аэропорт?</h3><p>Да. Мы предлагаем трансферы в одну сторону и туда-обратно. Закажите обратный трансфер с пляжа Лара в аэропорт Анталья при том же бронировании и получите скидку.</p><h3>Как найти водителя в аэропорту Анталья?</h3><p>Ваш водитель будет ждать в зале прилёта с табличкой с вашим именем. Мы отслеживаем рейс в режиме реального времени — при задержке водитель всё равно будет там, без доплаты.</p>', 'Трансфер Аэропорт Анталья — Пляж Лара | Частный VIP | ~20 мин', 'Частный VIP-трансфер из аэропорта Анталья на пляж Лара (Кунду). ~20 мин, 15 км. Фиксированная цена, встреча, отслеживание рейса. Лучше такси — бронируйте за 2 мин.', 'Antalya Havalimanı → Lara Beach Transfer', 'Lara Beach otellerine özel VIP transfer — Aska Lara, Titanic Lara, Royal Seginus. Sabit fiyat, taksi yok, bekleme yok.', '<p>Lara Beach (Kundu), Türkiye''nin en iyi 5 yıldızlı otellerine ev sahipliği yapan Antalya''nın en popüler tatil bölgelerinden biridir. Antalya Havalimanı''nın (AYT) sadece 15 km doğusunda yer alan Lara Beach, havalimanına en yakın büyük tatil bölgesidir — özel transferle yalnızca ~20 dakika.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>Taksiye göre özel transferin avantajları: Önceden sabit fiyat, isim tabelasıyla profesyonel şoför, uçuş gecikmelerinde ücretsiz bekleme — sürpriz yok.</p><h2>Lara Beach için Neden TORVIAN?</h2><ul><li>Antalya Havalimanı (AYT)''ndan Lara Beach''e kapıdan kapıya direkt transfer</li><li>Sabit fiyat — taksimetre yok, gizli ücret yok</li><li>Varış salonunda isim tabelasıyla karşılama</li><li>Ücretsiz uçuş takibi — gecikmede bekliyoruz</li><li>Klimalı, Wi-Fi ve çocuk koltuğu seçenekli Mercedes Vito VIP</li><li>24 saate kadar ücretsiz iptal</li><li>7/24 Türkçe WhatsApp desteği</li><li>Tüm Lara Beach otelleri: Aska Lara, Titanic, Royal Seginus ve diğerleri</li></ul><h2>Sık Sorulan Sorular</h2><h3>Lara Beach, Antalya Havalimanı''na ne kadar uzak?</h3><p>Lara Beach (Kundu bölgesi), Antalya Havalimanı''na (AYT) yaklaşık 15 km uzaklıktadır. Özel transferle yaklaşık 20 dakika sürer — bu, havalimanına en yakın büyük tatil bölgesidir.</p><h3>Özel transfer, Antalya Havalimanı''ndan Lara Beach''e taksiden daha ucuz mu?</h3><p>TORVIAN özel transferleri, yolculuk öncesinde belirlenen sabit fiyat sunar — sayaçla çalışan taksilerden farklı olarak. Gizli ücret yok, uçuş gecikmelerinde ücretsiz bekleme.</p><h3>Lara Beach''teki hangi otellere hizmet veriyorsunuz?</h3><p>Lara Beach ve Kundu bölgesindeki tüm otellere hizmet veriyoruz: Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace ve diğerleri. Rezervasyon sırasında otel adınızı girmeniz yeterli.</p><h3>Lara Beach''ten havalimanına dönüş transferi rezervasyonu yapabilir miyim?</h3><p>Evet. Hem tek yön hem de gidiş-dönüş transfer sunuyoruz. Aynı rezervasyonda Lara Beach''ten Antalya Havalimanı''na dönüş transferini seçerek indirimli fiyattan yararlanabilirsiniz.</p><h3>Antalya Havalimanı''nda şoförümü nasıl bulurum?</h3><p>Şoförünüz, adınızın yazılı olduğu tabela ile varış salonunda sizi bekleyecektir. Uçuşunuzu gerçek zamanlı takip ediyoruz — gecikmede şoförünüz yine de orada olacak, ek ücret yok.</p>', 'Antalya Havalimanı''ndan Lara Beach''e Transfer | Özel VIP | ~20 dk', 'Antalya Havalimanı''ndan Lara Beach (Kundu) özel VIP transfer. ~20 dk, 15 km. Sabit fiyat, karşılama, uçuş takibi. Taksiden daha iyi — 2 dakikada rezervasyon.', 'Luchthaven Antalya → Lara Beach Transfer', 'Privé VIP-transfer naar Lara Beach hotels — Aska Lara, Titanic Lara, Royal Seginus. Vaste prijs, geen taxi''s, geen wachttijd.', '<p>Lara Beach (Kundu) is een van de populairste resortgebieden van Antalya, met enkele van de beste 5-sterrenhotels van Turkije. Op slechts 15 km ten oosten van de luchthaven Antalya (AYT) is dit de dichtstbijzijnde grote bestemming — slechts ~20 minuten met een privétransfer. Sla de taxirij over en kom comfortabel aan.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>Waarom een privétransfer in plaats van een taxi? Vaste prijs vooraf afgesproken, professionele chauffeur met naambord, gratis wachttijd bij vluchtvertraging — geen verrassingen.</p><h2>Waarom TORVIAN voor Lara Beach?</h2><ul><li>Directe deur-tot-deur transfer van de luchthaven Antalya (AYT) naar Lara Beach</li><li>Vaste prijs — geen taxameter, geen piekprijzen, niet onderhandelen</li><li>Ontvangst met naambord in de aankomsthal</li><li>Gratis vluchtmonitoring — wij wachten bij vertraging</li><li>Mercedes Vito VIP met airco, wifi en kinderzitjes mogelijk</li><li>Gratis annuleren tot 24 uur voor vertrek</li><li>24/7 WhatsApp-ondersteuning in het Nederlands</li><li>Alle hotels in Lara Beach: Aska Lara, Titanic, Royal Seginus en meer</li></ul><h2>Veelgestelde vragen</h2><h3>Hoe ver ligt Lara Beach van de luchthaven Antalya?</h3><p>Lara Beach (Kundu-gebied) ligt ongeveer 15 km van de luchthaven Antalya (AYT). Een privétransfer duurt ongeveer 20 minuten — hiermee is het het dichtstbijzijnde grote resortgebied bij het vliegveld.</p><h3>Is een privétransfer goedkoper dan een taxi van de luchthaven Antalya naar Lara Beach?</h3><p>TORVIAN privétransfers hebben een vaste prijs die vooraf wordt afgesproken — in tegenstelling tot taxi''s met een taxameter. Geen verborgen kosten, geen piekprijzen, en uw chauffeur wacht gratis bij vluchtvertraging.</p><h3>Welke hotels in Lara Beach bedient u?</h3><p>Wij bedienen alle hotels in Lara Beach en Kundu, waaronder Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace en alle andere. Vul gewoon uw hotelnaam in tijdens het boeken.</p><h3>Kan ik een retourtransfer van Lara Beach naar de luchthaven Antalya boeken?</h3><p>Ja. Wij bieden zowel enkele reis als retourtransfers aan. Boek uw retourtransfer van Lara Beach naar de luchthaven Antalya in dezelfde boeking en ontvang een gecombineerde kortingsprijs.</p><h3>Hoe vind ik mijn chauffeur op de luchthaven Antalya?</h3><p>Uw chauffeur wacht in de aankomsthal met een bordje met uw naam. Wij volgen uw vlucht in realtime — bij vertraging staat uw chauffeur er nog steeds, zonder extra kosten.</p>', 'Luchthaven Antalya naar Lara Beach Transfer | Privé VIP | ~20 min', 'Privé VIP-transfer van de luchthaven Antalya naar Lara Beach (Kundu). ~20 min, 15 km. Vaste prijs, ontvangst met naambord, gratis vluchtmonitoring. Beter dan een taxi — boek online in 2 minuten.', 'Aeroportul Antalya → Transfer Lara Beach', 'Transfer privat VIP către hotelurile din Lara Beach — Aska Lara, Titanic Lara, Royal Seginus. Preț fix, fără taxiuri, fără așteptare.', '<p>Lara Beach (Kundu) este una dintre cele mai populare zone de stațiune din Antalya, cu câteva dintre cele mai bune hoteluri de 5 stele din Turcia. La doar 15 km est de Aeroportul Antalya (AYT), este cea mai apropiată destinație majoră — circa 20 de minute cu un transfer privat. Sari peste coada de la taxi și ajungi confortabil.</p><p>Aska Lara Resort &amp; Spa, Titanic Deluxe Lara, Royal Seginus, Rixos Downtown Antalya</p><p>De ce transfer privat în loc de taxi? Preț fix stabilit dinainte, șofer profesionist cu panou de întâmpinare, așteptare gratuită dacă zborul întârzie — fără surprize.</p><h2>De ce TORVIAN pentru Lara Beach?</h2><ul><li>Transfer direct din ușă în ușă de la Aeroportul Antalya (AYT) la Lara Beach</li><li>Preț fix — fără aparat de taxare, fără tarife majorate, fără negociere</li><li>Întâmpinare cu panou în holul de sosiri</li><li>Urmărirea zborului gratuită — așteptăm dacă ai întârziere</li><li>Mercedes Vito VIP cu aer condiționat, Wi-Fi și scaune pentru copii la cerere</li><li>Anulare gratuită cu până la 24 de ore înainte de plecare</li><li>Asistență WhatsApp 24/7</li><li>Toate hotelurile din Lara Beach: Aska Lara, Titanic, Royal Seginus și altele</li></ul><h2>Întrebări frecvente</h2><h3>La ce distanță este Lara Beach de Aeroportul Antalya?</h3><p>Lara Beach (zona Kundu) se află la aproximativ 15 km de Aeroportul Antalya (AYT). Un transfer privat durează în jur de 20 de minute — este cea mai apropiată zonă de stațiune majoră de aeroport.</p><h3>Un transfer privat este mai ieftin decât un taxi de la Aeroportul Antalya la Lara Beach?</h3><p>Transferurile private TORVIAN au un preț fix, stabilit dinainte — spre deosebire de taxiurile cu aparat de taxare. Fără costuri ascunse, fără tarife majorate, iar șoferul te așteaptă gratuit dacă zborul întârzie.</p><h3>Către ce hoteluri din Lara Beach faceți transfer?</h3><p>Deservim toate hotelurile din Lara Beach și Kundu, printre care Aska Lara Resort &amp; Spa, Titanic Deluxe Lara Beach Hotel, Royal Seginus Hotel, Rixos Downtown Antalya, Mardan Palace și toate celelalte. Este suficient să scrii numele hotelului la rezervare.</p><h3>Pot rezerva un transfer retur de la Lara Beach la Aeroportul Antalya?</h3><p>Da. Oferim atât curse dus, cât și dus-întors. Rezervă cursa de retur de la Lara Beach la Aeroportul Antalya în aceeași rezervare și primești un preț redus.</p><h3>Cum îmi găsesc șoferul în Aeroportul Antalya?</h3><p>Șoferul te așteaptă în holul de sosiri cu un panou pe care este scris numele tău. Îți urmărim zborul în timp real — dacă are întârziere, șoferul este tot acolo, fără costuri su